import React, { useState } from "react";
import "Login.css"; 

function Login() {
  const [userId, setUserId] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    // Your login logic here
    console.log("Login:", { userId, password });
  };

  return (
    <div className="d-flex justify-content-center align-items-center vh-100 bg-light">
      <div className="card shadow-sm p-4" style={{ width: "100%", maxWidth: "400px" }}>
        <img src="logo.png" alt="Zerodha Logo" className="mx-auto d-block mb-3" style={{ width: "40px" }} />
        <h5 className="text-center mb-4">Login to Kite</h5>

        <form onSubmit={handleSubmit}>
          <input
            type="text"
            className="form-control mb-3"
            placeholder="Phone number or User ID"
            value={userId}
            onChange={(e) => setUserId(e.target.value)}
            required
          />

          <input
            type="password"
            className="form-control mb-4"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          <button type="submit" className="btn btn-danger w-100 mb-2">
            Login
          </button>
        </form>

        <div className="text-center mb-3">
          <a href="#" className="small text-muted text-decoration-none">
            Forgot user ID or password?
          </a>
        </div>

        <hr />

        <div className="text-center">
          <small className="text-muted">
            Don't have an account? <a href="/signup" className="text-primary">Signup now!</a>
          </small>
        </div>
      </div>
    </div>
  );
}

export default Login;
